func TestParseValueQuotedHash(t *testing.T) {
	cases := map[string]string{
		`"Issue #42: retry"`: "Issue #42: retry",
		`8080 # http`:        "8080",
		`"x" # note`:         "x",
		`"C:\\temp"`:         `C:\temp`,
		`"a \"b\" #c"`:       `a "b" #c`,
	}
	for in, want := range cases {
		got, err := parseValue(in)
		if err != nil || got != want {
			t.Errorf("parseValue(%q) = %q, %v; want %q", in, got, err, want)
		}
	}
}
EOF
